mapper.select:
SELECT NATION_CODE , NATION_NAME , FTA_HS_CNT , RCEP_CNT FROM ( SELECT D.CODE AS NATION_CODE , D.CODE_NAME AS NATION_NAME , (SELECT COUNT(*) AS FTA_HS_CNT FROM FTA_HS_CODE FHC WHERE FHC.COMPANY_CODE = D.COMPANY_CODE AND FHC.NATION_CODE = D.CODE
AND FHC.ITEM_CODE LIKE CONCAT('%',#{searchItemCode} ,'%')
AND FHC.FTA_HS_CODE LIKE CONCAT(#{searchHsCode} ,'%')
) AS FTA_HS_CNT , (SELECT COUNT(*) AS RCEP_CNT FROM TARIFF_DIFFERENTIALS TDC WHERE TDC.NATION_CODE = D.CODE
AND TDC.HS_CODE LIKE CONCAT(#{searchHsCode} ,'%')
) AS RCEP_CNT FROM CODE_MST M INNER JOIN CODE_DTL D ON M.CATEGORY = D.CATEGORY AND M.COMPANY_CODE = D.COMPANY_CODE WHERE M.COMPANY_CODE = #{company_code} AND M.CATEGORY = 'NA' AND D.DELETE_YN = 'N'
AND (EXISTS (SELECT 1 FROM FTA_HS_CODE FH WHERE FH.COMPANY_CODE = D.COMPANY_CODE AND FH.NATION_CODE = D.CODE AND FH.FTA_HS_CODE LIKE CONCAT(#{searchHsCode} ,'%')) OR EXISTS (SELECT 1 FROM TARIFF_DIFFERENTIALS TD WHERE TD.NATION_CODE = D.CODE AND TD.HS_CODE LIKE CONCAT(#{searchHsCode} ,'%')) )
AND EXISTS (SELECT 1 FROM FTA_HS_CODE FH WHERE FH.COMPANY_CODE = D.COMPANY_CODE AND FH.NATION_CODE = D.CODE AND FH.ITEM_CODE LIKE CONCAT('%',#{searchItemCode} ,'%'))
) TA ORDER BY TA.FTA_HS_CNT DESC, TA.RCEP_CNT DESC, TA.NATION_CODE

SELECT A.FTA_CODE , F.FTA_NAME , A.NATION_CODE , A.HS_CODE , A.APPLY_DATE , A.END_DATE FROM TARIFF_DIFFERENTIALS A INNER JOIN FTA_MASTER F ON A.FTA_CODE = F.FTA_CODE AND F.COMPANY_CODE = #{company_code} WHERE A.NATION_CODE = #{nationCode}
AND A.HS_CODE LIKE CONCAT('%',#{searchHsCode} ,'%')
ORDER BY A.FTA_CODE, A.HS_CODE

SELECT COUNT(*)
  FROM FTA_HS_CODE
 WHERE ITEM_CODE = #{item_code}
   AND COMPANY_CODE = #{company_code}
   AND NATION_CODE = #{nation_code}
   AND FTA_HS_CODE = #{fta_hs_code}

mapper.update:
   UPDATE FTA_HS_CODE
	  SET REMARKS = #{remarks}
	    , UPDATE_DATE = NOW()
	    , UPDATE_BY = #{update_by}
	WHERE ITEM_CODE = #{item_code}
	  AND COMPANY_CODE = #{company_code}
	  AND NATION_CODE = #{nation_code}
	  AND FTA_HS_CODE = #{fta_hs_code}

mapper.delete:
DELETE FROM FTA_HS_CODE
 WHERE ITEM_CODE = #{item_code}
   AND COMPANY_CODE = #{company_code}
   AND NATION_CODE = #{nation_code}
   AND FTA_HS_CODE = #{fta_hs_code}

